<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { CLOUD_API, cloudSession, setCloudSession, signedIn, steamLoginUrl, keepCloudVoice, cloudBusy, cloudProgress } from '@/cloud/client'
import { extensionRequest, type ConnectorState, type SourceMatch } from '@/cloud/extension'
import { useRecentDemos, type RecentDemo } from '@/viewer/ingest/useRecentDemos'
import { fmtSize, mapImage, prettyMap } from '@/viewer/domain/demoMeta'
import { demoPath, UPLOAD_PATH } from '@/app/paths'
import { useI18n } from '@/app/i18n'
const { t, locale } = useI18n()
const route = useRoute(); const router = useRouter(); const recent = useRecentDemos()
const error = ref(''); const notice = ref(''); const loading = ref(false); const installed = ref(false)
const steamBusy = ref(false); const steamError = ref('')
const autoSteam = ref(localStorage.getItem('cs2d-steam-auto') !== 'off')
const nickname = ref('Al1askhan'); const search = ref(''); const sort = ref('date')
const source = ref('all'); const result = ref('all'); const map = ref('all')
const state = ref<ConnectorState>({ matches: [], active: [] })
const extensionDownload = import.meta.env.BASE_URL + 'cs2d-companion.zip?v=1.2.0'
const owner = '76561198920126438'
const selected = ref<string[]>([])
const allRecords = computed(() => recent.list.value.map(m => {
  const me = m.analysis?.players.find(p => p.steamId === owner)
  return { ...m, me, deagle: me?.weapons.find(w => w.weapon === 'deagle') }
}))
const records = computed(() => allRecords.value.filter(m =>
  `${m.title || ''} ${m.fileName} ${m.map} ${m.competition || ''}`.toLowerCase().includes(search.value.toLowerCase()) &&
  (source.value === 'all' || m.source === source.value) && (result.value === 'all' || m.outcome === result.value) && (map.value === 'all' || m.map === map.value)
).sort((a,b) => sort.value === 'deagle' ? (b.deagle?.kills ?? -1)-(a.deagle?.kills ?? -1) || (b.deagle?.hsPercent ?? 0)-(a.deagle?.hsPercent ?? 0) : sort.value === 'deagleHs' ? (b.deagle?.headshots ?? -1)-(a.deagle?.headshots ?? -1) : sort.value === 'hs' ? (b.me?.hsPercent ?? -1)-(a.me?.hsPercent ?? -1) : (b.date || b.savedAt)-(a.date || a.savedAt)))
const maps = computed(() => [...new Set(allRecords.value.map(m => m.map))].sort())
const personal = computed(() => allRecords.value.flatMap(m => m.me ? [m.me] : []))
const wins = computed(() => allRecords.value.filter(m => m.outcome === 'win').length)
const knownResults = computed(() => allRecords.value.filter(m => m.outcome).length)
const winRate = computed(() => knownResults.value ? Math.round(wins.value / knownResults.value * 100) + '%' : '—')
const averageAdr = computed(() => personal.value.length ? Math.round(personal.value.reduce((sum,p) => sum+p.adr,0)/personal.value.length) : '—')
const kd = computed(() => personal.value.length ? (personal.value.reduce((sum,p) => sum+p.kills,0)/Math.max(1,personal.value.reduce((sum,p) => sum+p.deaths,0))).toFixed(2) : '—')
const bestDeagle = computed(() => personal.value.length ? Math.max(0,...allRecords.value.map(m => m.deagle?.kills || 0)) : '—')
const groups = computed(() => {
  const groups = new Map<string, typeof records.value>()
  for (const m of records.value) {
    const key = sort.value === 'date' ? formatDate(m.date || m.savedAt, false) : t('cloud.filteredMatches')
    groups.set(key, [...groups.get(key) || [],m])
  }
  return [...groups].map(([label,matches]) => ({ label, matches }))
})
const imports = computed(() => state.value.matches.filter(m => !recent.list.value.some(r => r.source === m.source && r.sourceId === m.id)))
const steamStatus = computed(() => steamBusy.value ? t('cloud.steamChecking') : state.value.steam?.loginRequired ? t('cloud.steamNeedsLogin') : steamError.value || state.value.steam?.error ? t('cloud.steamFailed') : state.value.steam?.checkedAt ? t('cloud.steamUpdated') + ' ' + formatTime(state.value.steam.checkedAt) : t('cloud.steamWaiting'))
function formatDate(ms: number, time = true) { return new Intl.DateTimeFormat(locale.value,{day:'numeric',month:'short',year:'numeric',...(time?{hour:'2-digit',minute:'2-digit'} as const:{})}).format(ms) }
function formatTime(ms: number) { return new Intl.DateTimeFormat(locale.value,{hour:'2-digit',minute:'2-digit'}).format(ms) }
function modeLabel(m: { source?: string; mode?: string; competition?: string }) { return m.competition || (m.source === 'faceit' ? 'FACEIT · 5v5' : m.mode ? t(`cloud.mode.${m.mode}`) : m.source === 'steam' ? 'Steam · CS2' : t('cloud.uploadedDemo')) }
function outcomeLabel(m: RecentDemo) { return m.outcome ? t(`cloud.result.${m.outcome}`) : t('cloud.result.unknown') }
async function run(task: () => Promise<void>) { loading.value = true; error.value = ''; notice.value = ''; try { await task() } catch(e) { error.value = e instanceof Error ? e.message : String(e) } finally { loading.value = false } }
async function pair() { await extensionRequest('CLOUD_CONFIG', { api: CLOUD_API, token: cloudSession(), keepVoice: keepCloudVoice.value }) }
async function updateState() { if (installed.value) state.value = await extensionRequest<ConnectorState>('SOURCES_STATE', {}, 5000) }
async function syncFaceit() { await run(async () => { await pair(); await extensionRequest('FACEIT_SYNC', { nickname: nickname.value }, 90000); await updateState() }) }
async function syncSteam(force = false) {
  if (!installed.value || !signedIn.value || steamBusy.value) return
  steamBusy.value = true; steamError.value = ''
  try { await pair(); await extensionRequest('STEAM_SYNC', { force, autoImport: autoSteam.value }, 90000); await updateState() }
  catch(e) { steamError.value = e instanceof Error ? e.message : String(e) }
  finally { steamBusy.value = false }
}
async function importSelected() { await run(async () => { await pair(); for (const id of selected.value) { const item = imports.value.find(m => `${m.source}:${m.id}` === id); if (item) await extensionRequest('IMPORT_MATCH', { source: item.source, id: item.id }) } selected.value = []; await updateState(); notice.value = t('cloud.queued') }) }
function selectAll() { selected.value = imports.value.map(m => `${m.source}:${m.id}`) }
function toggle(m: SourceMatch) { const id = `${m.source}:${m.id}`; selected.value = selected.value.includes(id) ? selected.value.filter(x => x !== id) : [...selected.value,id] }
async function signOut() {
  if (installed.value) {
    try { await extensionRequest('STEAM_AUTO_IMPORT', { enabled: false }); await extensionRequest('CLOUD_CONFIG', { api: CLOUD_API, token: '' }) } catch { /* the site session is still cleared below */ }
  }
  setCloudSession(''); recent.list.value = []; state.value = { matches: [], active: [] }
}
watch(autoSteam, async enabled => {
  localStorage.setItem('cs2d-steam-auto', enabled ? 'on' : 'off')
  if (!signedIn.value || !installed.value) return
  await run(async () => { await pair(); await extensionRequest('STEAM_AUTO_IMPORT', { enabled }); if (enabled) void syncSteam(true) })
})
let timer: ReturnType<typeof setInterval> | undefined
let polling = false; let wasImporting = false; let nextSteamCheck = 0
onMounted(async () => {
  const session = route.query.session
  if (typeof session === 'string') { setCloudSession(session); await router.replace('/cloud') }
  try { const companion = await extensionRequest<{version:string}>('PING', {}, 2500); installed.value = true; if (companion.version.localeCompare('1.2.0',undefined,{numeric:true}) < 0) { installed.value = false; notice.value = t('cloud.updateExtension') } } catch { /* install instructions stay visible */ }
  if (signedIn.value) await run(async () => {
    await recent.refresh()
    if (installed.value) {
      await pair(); await extensionRequest('STEAM_AUTO_IMPORT', { enabled: autoSteam.value }); await updateState()
      if (autoSteam.value) { nextSteamCheck = Date.now()+300000; void syncSteam() }
    }
  })
  timer = setInterval(async () => {
    if (polling || !signedIn.value || !installed.value || document.hidden) return
    polling = true
    try {
      const previousVersion = state.value.libraryVersion
      await updateState()
      const importing = state.value.active.some(j => !j.error)
      if (importing || wasImporting || state.value.libraryVersion !== previousVersion) await recent.refresh()
      wasImporting = importing
      if (autoSteam.value && Date.now() >= nextSteamCheck) { nextSteamCheck = Date.now()+300000; void syncSteam() }
    } catch { /* preserve the last successful state */ } finally { polling = false }
  },3000)
})
onUnmounted(() => clearInterval(timer))
</script>

<template>
  <main class="cloud-page"><div class="cloud-content">
    <header class="page-heading"><div><p class="eyebrow">CS2D <span>/</span> PERSONAL STATS</p><h1>{{ t('cloud.historyTitle') }}</h1><p>{{ t('cloud.historySubtitle') }}</p></div><div class="heading-actions"><RouterLink :to="UPLOAD_PATH" class="secondary">＋ {{ t('cloud.openFile') }}</RouterLink><button v-if="signedIn" class="secondary icon-button" :aria-label="t('cloud.refresh')" :disabled="loading" @click="run(recent.refresh)">↻</button></div></header>
    <p v-if="error" role="alert" class="message error">{{ error }}</p><p v-if="notice" role="status" class="message success">{{ notice }}</p>
    <section v-if="!signedIn" class="login-card"><div class="login-art" :style="{backgroundImage:`linear-gradient(90deg,#22272f15,#22272f),url('${mapImage('de_nuke')}')`}"><span class="crosshair">⊕</span></div><div class="login-content"><p class="eyebrow">YOUR GAME. YOUR HISTORY.</p><h2>{{ t('cloud.loginTitle') }}</h2><p>{{ t('cloud.loginBody') }}</p><a :href="steamLoginUrl()" class="primary">{{ t('cloud.signIn') }} ↗</a><small>{{ t('cloud.private') }}</small></div></section>
    <section v-if="signedIn" class="profile-panel"><div class="profile-identity"><div class="avatar">A<span></span></div><div><h2>Al1askhan <span>CS2</span></h2><p>{{ t('cloud.personalLibrary') }}</p><div class="source-pills"><span>Steam</span><span class="faceit-pill">FACEIT</span><span class="cloud-pill">☁ {{ t('cloud.cloudBadge') }}</span></div></div></div><div class="profile-metrics"><article><small>{{ t('cloud.matchesLabel') }}</small><strong>{{ allRecords.length }}</strong></article><article><small>{{ t('cloud.winRate') }}</small><strong class="green">{{ winRate }}</strong></article><article><small>K/D</small><strong>{{ kd }}</strong></article><article><small>ADR</small><strong>{{ averageAdr }}</strong></article><button @click="sort='deagle';source='all';result='all';map='all';search=''" class="deagle-summary"><small>{{ t('cloud.deagleRecord') }} ↗</small><strong>{{ bestDeagle }} <em>K</em></strong></button></div></section>
    <details class="connections-panel" :open="!installed || state.steam?.loginRequired || !!steamError"><summary class="connections-heading"><h2>{{ t('cloud.sources') }} <i class="disclosure">⌄</i></h2><span :class="{ready:installed}"><i></i>{{ installed ? t('cloud.companionReady') : t('cloud.companionMissing') }}<b v-if="installed&&autoSteam"> · Steam {{ t('cloud.auto') }}</b></span></summary>
      <div class="source-grid"><section class="source-card steam-card"><div class="source-top"><div class="source-logo steam-logo">S</div><div><h3>Steam</h3><p>{{ t('cloud.steamHistory') }}</p></div><label class="switch"><input v-model="autoSteam" type="checkbox"><span></span><b>{{ t('cloud.auto') }}</b></label></div><p class="source-description">{{ t('cloud.autoSteamBody') }}</p><div class="source-bottom"><span class="status" :class="{ready:state.steam?.checkedAt&&!state.steam.loginRequired&&!state.steam.error&&!steamError,pending:steamBusy}"><i></i>{{ steamStatus }}</span><button class="text-button" :disabled="!signedIn||!installed||steamBusy" @click="syncSteam(true)">{{ steamBusy ? '…' : '↻' }} {{ t('cloud.checkNow') }}</button></div><a v-if="state.steam?.loginRequired" href="https://steamcommunity.com/login/home/" target="_blank" rel="noopener" class="login-steam">{{ t('cloud.loginSteamBrowser') }} ↗</a><p v-if="steamError||state.steam?.error" class="inline-error">{{ steamError || state.steam?.error }}</p></section>
      <section class="source-card"><div class="source-top"><div class="source-logo faceit-logo">F</div><div><h3>FACEIT</h3><p>{{ state.faceit?.nickname || t('cloud.connectFaceit') }}</p></div><span v-if="state.faceit" class="connected-label">● {{ t('cloud.connected') }}</span></div><p class="source-description">{{ t('cloud.faceitBody') }}</p><div class="source-controls"><input v-model="nickname" :placeholder="t('cloud.nickname')" aria-label="FACEIT nickname"><button class="secondary" :disabled="!signedIn||!installed||loading" @click="syncFaceit">{{ loading ? '…' : t('cloud.sync') }}</button></div></section></div>
      <details v-if="!installed" class="extension-card" open><summary>{{ t('cloud.extensionTitle') }}</summary><div><ol><li>{{ t('cloud.install1') }}</li><li>{{ t('cloud.install2') }}</li><li>{{ t('cloud.install3') }}</li></ol><a :href="extensionDownload" download class="primary">{{ t('cloud.downloadExtension') }} · 1.2.0 ↓</a></div></details>
    </details>
    <section v-if="state.active.length || cloudBusy" class="jobs"><div class="panel-heading"><h2>{{ t('cloud.processing') }}</h2><span>{{ state.active.filter(j=>!j.error).length }} {{ t('cloud.inProgress') }}</span></div><p v-if="cloudBusy">{{ t('cloud.cloudUpload') }} · {{ cloudProgress }}%</p><div v-for="job in state.active" :key="job.matchId" class="job-row"><div><strong>{{ job.meta?.map ? prettyMap(job.meta.map) : job.label?.startsWith('de_') ? prettyMap(job.label) : t('cloud.cs2Match') }}</strong><small>{{ job.meta?.source?.toUpperCase() || 'CS2' }}</small></div><span :class="{red:job.error}">{{ job.error || t(`cloud.phase.${job.phase}`) }} <b v-if="!job.error&&job.total">{{ Math.min(100,Math.round((job.loaded||0)/job.total*100)) }}%</b></span></div></section>
    <details v-if="signedIn&&imports.length" class="imports-panel"><summary>{{ t('cloud.available') }} <span>{{ imports.length }}</span><small>{{ t('cloud.chooseImports') }}</small></summary><div class="imports-content"><p>{{ t('cloud.expiryHint') }}</p><div class="import-actions"><button class="secondary" @click="selectAll">{{ t('cloud.selectAll') }}</button><button class="primary" :disabled="loading||!selected.length" @click="importSelected">{{ t('cloud.import') }} ({{ selected.length }})</button></div><div class="import-list"><label v-for="m in imports" :key="`${m.source}:${m.id}`"><input type="checkbox" :checked="selected.includes(`${m.source}:${m.id}`)" @change="toggle(m)"><b>{{ m.source.toUpperCase() }}</b><strong>{{ m.map ? prettyMap(m.map) : t('cloud.cs2Match') }}</strong><span>{{ modeLabel(m) }}</span><time v-if="m.date">{{ formatDate(m.date) }}</time><small v-if="m.kills!=null">{{ m.kills }} K · {{ m.hsPercent ?? '—' }}% HS</small></label></div></div></details>
    <section class="history-section"><div class="history-heading"><div><h2>{{ t('cloud.matchHistory') }} <span>{{ allRecords.length }}</span></h2><p>{{ t('cloud.recordsHint') }}</p></div><div class="storage-compact" :title="t('cloud.storageBody')"><span>☁</span><div><strong>{{ fmtSize(recent.totalBytes.value) }} <small>/ {{ fmtSize(recent.maxBytes.value) }}</small></strong><div class="storage-track"><i :style="{width:`${Math.min(100,recent.totalBytes.value/recent.maxBytes.value*100)}%`}"></i></div><p>{{ t('cloud.cloudOnly') }}</p></div></div></div>
      <div class="history-tabs"><button v-for="tab in ['all','win','loss','draw']" :key="tab" :class="{selected:result===tab}" @click="result=tab">{{ t(`cloud.tab.${tab}`) }}<span v-if="tab==='all'">{{ allRecords.length }}</span></button></div>
      <div class="library-filters"><label><span>{{ t('cloud.platform') }}</span><select v-model="source"><option value="all">{{ t('cloud.allSources') }}</option><option value="steam">Steam</option><option value="faceit">FACEIT</option><option value="imported">{{ t('cloud.uploadedDemo') }}</option></select></label><label><span>{{ t('cloud.mapLabel') }}</span><select v-model="map"><option value="all">{{ t('cloud.allMaps') }}</option><option v-for="m in maps" :key="m" :value="m">{{ prettyMap(m) }}</option></select></label><label class="sort-filter"><span>{{ t('cloud.sortLabel') }}</span><select v-model="sort"><option value="date">{{ t('cloud.sortDate') }}</option><option value="deagle">{{ t('cloud.sortDeagle') }}</option><option value="deagleHs">{{ t('cloud.sortDeagleHs') }}</option><option value="hs">{{ t('cloud.sortHs') }}</option></select></label><input v-model="search" :placeholder="t('cloud.search')" :aria-label="t('cloud.search')"></div>
      <div v-if="records.length" class="match-groups"><section v-for="group in groups" :key="group.label" class="match-session"><header class="session-heading"><strong>{{ group.label }}</strong><span>{{ t('cloud.matchesCount') }}: {{ group.matches.length }}</span><span class="session-record"><b class="green" v-if="group.matches.some(m=>m.outcome==='win')">{{ group.matches.filter(m=>m.outcome==='win').length }} W</b><b class="red" v-if="group.matches.some(m=>m.outcome==='loss')">{{ group.matches.filter(m=>m.outcome==='loss').length }} L</b></span></header><div class="table-head"><span>{{ t('cloud.mapLabel') }} / {{ t('cloud.platform') }}</span><span>{{ t('cloud.scoreLabel') }}</span><span>K / D / A</span><span>ADR</span><span>HS%</span><span>Desert Eagle</span><span></span></div>
      <RouterLink v-for="m in group.matches" :key="m.id" :to="`${demoPath(m.id)}/overview`" class="match-row" :class="m.outcome||'neutral'"><div class="match-map"><div class="map-art" :style="{backgroundImage:`linear-gradient(0deg,#1c212b50,#1c212b10),url('${mapImage(m.map)}')`}"><span>CS2</span></div><div class="map-info"><h3>{{ prettyMap(m.map) || t('cloud.cs2Match') }}</h3><p><span :class="{orange:m.source==='faceit'}">{{ m.source==='faceit' ? 'FACEIT' : m.source==='steam' ? 'STEAM' : 'DEMO' }}</span> · {{ modeLabel(m).replace(/^FACEIT · /,'') }}</p><time>{{ m.date ? formatDate(m.date) : t('cloud.added')+' '+formatDate(m.savedAt) }}</time><small v-if="m.title">{{ m.title }}</small></div></div><div class="match-score"><strong>{{ m.myScore ?? m.scoreCt }} <i>:</i> {{ m.opponentScore ?? m.scoreT }}</strong><span>{{ outcomeLabel(m) }}</span><small v-if="m.myScore==null">{{ m.teamCt || 'CT' }} / {{ m.teamT || 'T' }}</small><small v-else>{{ t('cloud.youVsOpponents') }}</small></div><div class="match-stat kda"><small>K / D / A</small><strong v-if="m.me">{{ m.me.kills }} <i>/ {{ m.me.deaths }} / {{ m.me.assists }}</i></strong><strong v-else>—</strong></div><div class="match-stat"><small>ADR</small><strong>{{ m.me ? m.me.adr.toFixed(1) : '—' }}</strong></div><div class="match-stat"><small>HS%</small><strong>{{ m.me ? m.me.hsPercent.toFixed(1)+'%' : '—' }}</strong></div><div class="match-stat deagle-stat"><small>Desert Eagle</small><strong>{{ m.deagle ? m.deagle.kills+' K' : m.me ? '0 K' : '—' }}</strong><span v-if="m.deagle">{{ m.deagle.headshots }} HS · {{ m.deagle.hsPercent.toFixed(0) }}%</span></div><div class="match-open"><span>{{ t('cloud.analyze') }} ↗</span><small>{{ m.analysis?.moments.length ?? 0 }} {{ t('cloud.moments') }}</small></div></RouterLink></section></div>
      <div v-else class="library-empty"><div class="empty-crosshair">⊕</div><h3>{{ allRecords.length ? t('cloud.noFilterMatches') : t('cloud.emptyTitle') }}</h3><p>{{ allRecords.length ? t('cloud.changeFilters') : t('cloud.emptyBody') }}</p><button v-if="allRecords.length" class="secondary" @click="search='';source='all';result='all';map='all'">{{ t('cloud.resetFilters') }}</button></div>
    </section>
    <details v-if="signedIn" class="preferences"><summary>{{ t('cloud.storageSettings') }}</summary><label><input v-model="keepCloudVoice" type="checkbox">{{ t('cloud.keepVoice') }}<small>{{ t('cloud.voiceHint') }}</small></label><p>{{ t('cloud.storageBody') }}</p></details>
    <footer><span>{{ t('cloud.footer') }}</span><button v-if="signedIn" @click="signOut">{{ t('cloud.signOut') }} ↗</button></footer>
  </div></main>
</template>

